document.addEventListener('DOMContentLoaded', function() {
  'use strict';

  // Get elements
  var toc = document.getElementById('toc-nav'),
      tocList = document.getElementById('toc-list'),
      autoSlideCheckbox = document.getElementById('auto-slide'),
      slides = document.querySelectorAll('.slide'),
      main = document.getElementById('slides-container'),
      prevBtn = document.getElementById('prev'),
      nextBtn = document.getElementById('next'),
      counter = document.getElementById('counter'),
      tocClosedBtn = document.querySelector('.btn-toc-close'),
      tocNavBtn = document.querySelector('.btn-toc-nav');

  var current = 0,
      total = slides.length,
      autoSlide = false,
      timer = null,
      tocVisible = false;

  // Generate TOC
  function generateTOC() {
    tocList.innerHTML = '';
    slides.forEach(function(slide, i) {
      var li = document.createElement('li');
      var h1 = slide.querySelector('h1');
      if (h1) {
        li.textContent = (i + 1) + '. ' + h1.textContent;
      } else {
        li.textContent = (i + 1) + ' - ' + slide.id.split('-')[1] + ' slide content';
      }
      li.onclick = function() { gotoSlide(i); };
      tocList.appendChild(li);
    });
  }

  // Update slide visibility
  function update() {
    slides.forEach(function(slide, i) {
      if (i === current && !slide.classList.contains('slide-hidden')) {
        slide.style.display = 'block';
        slide.style.display = 'flex';
        if (!slide.classList.contains('hidden-content')) {
          slide.classList.add('slide-active');
        }
      } else {
        slide.classList.remove('slide-active');
      }
    });

    if (counter) {
      counter.textContent = (current + 1) + ' / ' + total;
    }

    // Update TOC active state
    var tocItems = tocList.querySelectorAll('li');
    tocItems.forEach(function(item, i) {
      if (i === current) {
        item.style.color = '#6366f1';
        item.fontWeight = '600';
      } else {
        item.style.color = '#e5e7eb';
        item.fontWeight = '400';
      }
    });

    main.setAttribute('data-closed', toc ? '' : 'closed');
  }

  // Go to slide
  function gotoSlide(n) {
    if (n < 0) n = total - 1;
    if (n >= total) n = 0;
    current = n;
    clearAutoSlide();
    update();
  }

  // Next slide
  function next() {
    current = current >= total - 1 ? 0 : current + 1;
    update();
    // Restart auto-slide if enabled
    if (autoSlide) {
      timer = setInterval(next, 5000);
    }
  }

  // Prev slide
  function prev() {
    current = current === 0 ? total - 1 : current - 1;
    update();
  }

  // Clear auto-slide timer
  function clearAutoSlide() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  // Auto-slide toggle
  if (autoSlideCheckbox) {
    autoSlideCheckbox.checked = false; // Default off
    autoSlideCheckbox.onchange = function() {
      var checked = this.checked;
      if (checked) {
        autoSlide = true;
        timer = setInterval(next, 5000);
      } else {
        autoSlide = false;
        clearAutoSlide();
      }
    };
  }

  // Toggle TOC sidebar
  function toggleTOC() {
    tocVisible = !tocVisible;
    toc.style.display = tocVisible ? 'block' : 'none';
    toc.classList.toggle('visible', tocVisible);

    if (tocVisible) {
      main.setAttribute('data-closed', 'false');
    } else {
      main.setAttribute('data-closed', 'true');
    }

    // Update button states
    if (tocNavBtn) {
      tocNavBtn.textContent = tocVisible ? '↩️' : '❌';
    }

    if (tocClosedBtn) {
      tocClosedBtn.style.display = tocVisible ? 'none' : 'inline-block';
    }
  }

  // Button events
  if (prevBtn) prevBtn.addEventListener('click', prev);
  if (nextBtn) nextBtn.addEventListener('click', next);

  if (tocNavBtn) tocNavBtn.addEventListener('click', toggleTOC);
  if (tocClosedBtn) tocClosedBtn.addEventListener('click', toggleTOC);

  // Toggle sidebar on content click
  main.addEventListener('click', function(e) {
    if (e.target === toc) {
      toggleTOC();
    }
  });

  // Sidebar click to close on mobile
  toc.addEventListener('click', function(e) {
    if (tocVisible && e.target === toc) {
      toggleTOC();
    }
  });

  // Keyboard navigation
  document.addEventListener('keydown', function(e) {
    // Don't prevent default if input focused
    if (e.target && e.target.tagName === 'INPUT') return;

    switch (e.key) {
      case 'ArrowRight':
      case 'ArrowDown':
      case 'Enter':
      case ' ':
        gotoSlide(current + 1);
        e.preventDefault();
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        gotoSlide(current - 1);
        e.preventDefault();
        break;
      case 'n':
      case 'N':
        // Toggle TOC with 'N' key
        toggleTOC();
        e.preventDefault();
        break;
      case 'Escape':
        if (document.fullscreenElement) {
          document.exitFullscreen();
        }
        e.preventDefault();
        break;
      case 'Home':
        current = 0;
        update();
        e.preventDefault();
        break;
      case 'End':
        current = total - 1;
        update();
        e.preventDefault();
        break;
      case 't':
      case 'T':
        toggleTOC();
        e.preventDefault();
        break;
    }
  });

  // Touch swipe
  var touchStartY = 0, touchEndY = 0;
  main.addEventListener('touchstart', function(e) {
    touchStartY = e.changedTouches[0].screenY;
  }, false);

  main.addEventListener('touchend', function(e) {
    touchEndY = e.changedTouches[0].screenY;
    if (touchEndY - touchStartY > 50) { // Swipe down
      gotoSlide(current + 1);
    }
    if (touchStartY - touchEndY > 50) { // Swipe up
      gotoSlide(current - 1);
    }
  }, false);

  // Auto-slide on mouse up
  document.addEventListener('mousedown', clearAutoSlide);
  document.addEventListener('mouseup', function() {
    if (autoSlide) {
      timer = setInterval(next, 5000);
    }
  });

  // Initial setup
  if (tocNavBtn) tocNavBtn.textContent = '❌';
  if (tocClosedBtn) tocClosedBtn.style.display = 'none';

  generateTOC();
  update();

  // Start auto-slide if enabled
  if (autoSlideCheckbox && autoSlideCheckbox.checked) {
    autoSlide = true;
    timer = setInterval(next, 5000);
  }

});

/* Slide show styles for agent_call.html */
:root {
  --bg-primary: #111827;
  --bg-secondary: #1f2937;
  --code-bg: #0f0f0f;
  --primary-color: #6366f1;
  --text-color: #e5e7eb;
  --border-color: #374151;
}

/* Basic reset */
.slide-container *, .slide-container *:before, .slide-container *:after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Main container */
.slide-app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  padding: 0.5rem;
  background: var(--bg-secondary);
}

/* Header */
.slide-header {
  display: flex;
  align-items: center;
  padding: 0.5rem 1rem;
  gap: 0.5rem;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
}

.slide-header .logo {
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--primary-color);
  white-space: nowrap;
}

.main-content {
  flex: 1;
  display: flex;
  overflow: hidden;
  gap: 0.5rem;
}

/* Sidebar */
.slide-sidebar {
  flex-shrink: 0;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  padding: 0.75rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  border-radius: 4px;
  flex: 0 0 auto;
  overflow: hidden;
  transition: width 0.3s ease, left 0.3s ease;
}

.slide-sidebar[hidden],
.slide-sidebar.hidden {
  display: none;
}

.slide-sidebar h2 {
  font-size: 0.9rem;
  color: #e5e7eb;
  padding: 0.25rem 0;
  margin: 0;
  font-weight: 600;
}

.slide-sidebar ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.slide-sidebar li {
  font-size: 0.9rem;
  padding: 0.4rem 0.6rem;
  color: var(--text-color);
  cursor: pointer;
  border-radius: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: background 0.2s, color 0.2s;
}

.slide-sidebar li:hover {
  background: var(--border-color);
}

.slide-sidebar li.active {
  color: var(--primary-color);
  font-weight: 600;
  background: rgba(99, 102, 241, 0.1);
}

/* Slide panel area */
.slide-panel {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  gap: 0.5rem;
}

/* Sliding container with scroll */
.sliding {
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  scroll-behavior: smooth;
  scroll-padding: 1rem 0;
}

/* Individual slide */
.slide {
  padding: 1rem;
  margin: 0;
  background: var(--bg-primary);
  border: none;
  color: var(--text-color);
  display: none;
}

.slide.active,
.slide.slide-active {
  display: flex;
  flex-grow: 1;
  border-radius: 0;
}

.slide.hidden-content {
  /* Hidden by JS, but in case */
  display: none;
}

.slide-slides {
  display: flex;
  flex-direction: column;
  gap: 3rem;
}

.slide-slides .slide {
  display: flex;
  flex-direction: column;
  padding: 1rem;
  min-height: 300px;
  border-radius: 8px;
}

.slide-slides .slide.active {
  display: flex;
}

.slide .code-panel,
.slide .sub-slide {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.slide h1 {
  color: var(--primary-color);
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.slide p,
.slide ul,
.slide button,
.slide div {
  margin: 0.5rem 0;
  line-height: 1.4;
}

.slide ul {
  list-style: disc;
  padding-left: 1.5rem;
  font-size: 0.95rem;
}

.slide ul li {
  margin-bottom: 0.25rem;
}

.slide pre {
  background: var(--code-bg);
  padding: 1rem;
  border-radius: 4px;
  overflow-x: auto;
  font-family: 'SF Mono', 'Monaco', 'Inconsolata', 'Fira Code', 'Source Code Pro', monospace;
  font-size: 0.85rem;
  line-height: 1.5;
  color: #e5e7eb;
  white-space: pre-wrap;
  word-break: break-all;
}

.slide pre code {
  font-size: inherit;
}

.slide button {
  display: inline-block;
  padding: 0.4rem 0.8rem;
  margin-top: 0.5rem;
  background: var(--primary-color);
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.9rem;
}

.slide button:hover {
  background: #5558e4;
}

.slide button:active {
  background: #4e53d3;
}

/* Footer */
.slide-footer {
  height: auto;
  padding: 0.5rem;
  background: var(--bg-primary);
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
}

.slide-counter {
  font-size: 0.8rem;
  color: var(--primary-color);
  font-weight: 500;
}

.slide-nav {
  display: flex;
  gap: 0.5rem;
}

.slide-nav button {
  padding: 0.3rem;
  background: var(--primary-color);
  color: white;
  border: none;
  border-radius: 4px;
  font-weight: 600;
  font-size: 0.8rem;
  min-width: 32px;
}

.slide-nav button:hover {
  background: #5558e4;
}

/* Toast hint */
.reload-hint,
.auto-slide-hint {
  position: fixed;
  bottom: 6px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary-color);
  color: #e5e7eb;
  padding: 0.25rem 0.5rem;
  border-radius: 3px;
  font-size: 0.8rem;
  font-weight: 700;
  z-index: 100;
  white-space: nowrap;
  transition: opacity 0.3s;
}

.reload-hint.hide,
.auto-slide-hint.hide {
  opacity: 0;
  pointer-events: none;
}

/* Scrollbar styling */
.slide-panel::-webkit-scrollbar {
  width: 4px;
}

.slide-panel::-webkit-scrollbar-track {
  background: transparent;
}

.slide-panel::-webkit-scrollbar-thumb {
  background: #4b5563;
  border-radius: 2px;
}

.slide-panel::-webkit-scrollbar-thumb:hover {
  background: #6b7280;
}

/* TOC button */
.btn-toc-nav,
.btn-toc-close {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem 0.5rem;
  background: var(--primary-color);
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-toc-nav:hover,
.btn-toc-close:hover {
  background: #5558e4;
}

.btn-toc-close {
  display: none;
}

/* Responsive styles */
@media (max-width: 768px) {
  .slide-app {
    padding: 0.25rem;
  }

  .slide-header {
    padding: 0.4rem 0.5rem;
    gap: 0.25rem;
  }

  .slide-header .logo {
    font-size: 0.9rem;
  }

  .slide-sidebar {
    padding: 0.5rem;
    display: none;
    background: var(--bg-primary);
    border: none;
  }

  .slide-sidebar[hidden],
  .slide-sidebar.hidden {
    display: none;
  }

  /* Show sidebar on close */
  .main-content[data-closed="true"] .slide-sidebar {
    width: auto;
    display: flex;
    left: 0;
    right: 0;
    height: 100vh;
    border-right: none;
    border-top: 1px solid var(--border-color);
    padding: 0.5rem;
    gap: 0.25rem;
    flex-direction: column;
  }

  .main-content[data-closed="true"] .slide-panel {
    width: 100%;
    margin-left: 0;
  }

  .slide h1 {
    font-size: 1.25rem;
  }

  .slide-nav button {
    min-width: 28px;
    font-size: 0.7rem;
  }

  .reload-hint,
  .auto-slide-hint {
    bottom: 4px;
  }
}

@media (max-width: 480px) {
  .reload-hint,
  .auto-slide-hint {
    bottom: 4px;
    left: auto;
    right: 6px;
    padding: 0.2rem 0.4rem;
    font-size: 0.8rem;
  }

  .slide-counter {
    font-size: 0.75rem;
  }
}

/* Animation fade in */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.slide.active,
.slide-slides .slide.active {
  animation: fadeIn 0.3s ease-out;
}

/* Highlight current slide in main content */
.slide-slides .slide.active {
  outline: 1px solid rgba(99, 102, 241, 0.3);
  outline-offset: -1px;
}

/* Code panel wrapper */
.code-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

