document.addEventListener('DOMContentLoaded', function() {
  'use strict';

  // Get elements
  var toc = document.getElementById('toc-nav'),
      tocList = document.getElementById('toc-list'),
      autoSlideCheckbox = document.getElementById('auto-slide'),
      slides = document.querySelectorAll('.slide'),
      main = document.getElementById('slides-container'),
      prevBtn = document.getElementById('prev'),
      nextBtn = document.getElementById('next'),
      counter = document.getElementById('counter'),
      tocClosedBtn = document.querySelector('.btn-toc-close'),
      tocNavBtn = document.querySelector('.btn-toc-nav');

  var current = 0,
      total = slides.length,
      autoSlide = false,
      timer = null,
      tocVisible = false;

  // Generate TOC
  function generateTOC() {
    tocList.innerHTML = '';
    slides.forEach(function(slide, i) {
      var li = document.createElement('li');
      var h1 = slide.querySelector('h1');
      if (h1) {
        li.textContent = (i + 1) + '. ' + h1.textContent;
      } else {
        li.textContent = (i + 1) + ' - ' + slide.id.split('-')[1] + ' slide content';
      }
      li.onclick = function() { gotoSlide(i); };
      tocList.appendChild(li);
    });
  }

  // Update slide visibility
  function update() {
    slides.forEach(function(slide, i) {
      if (i === current && !slide.classList.contains('slide-hidden')) {
        slide.style.display = 'block';
        slide.style.display = 'flex';
        if (!slide.classList.contains('hidden-content')) {
          slide.classList.add('slide-active');
        }
      } else {
        slide.classList.remove('slide-active');
      }
    });

    if (counter) {
      counter.textContent = (current + 1) + ' / ' + total;
    }

    // Update TOC active state
    var tocItems = tocList.querySelectorAll('li');
    tocItems.forEach(function(item, i) {
      if (i === current) {
        item.style.color = '#6366f1';
        item.fontWeight = '600';
      } else {
        item.style.color = '#e5e7eb';
        item.fontWeight = '400';
      }
    });

    main.setAttribute('data-closed', toc ? '' : 'closed');
  }

  // Go to slide
  function gotoSlide(n) {
    if (n < 0) n = total - 1;
    if (n >= total) n = 0;
    current = n;
    clearAutoSlide();
    update();
  }

  // Next slide
  function next() {
    current = current >= total - 1 ? 0 : current + 1;
    update();
    // Restart auto-slide if enabled
    if (autoSlide) {
      timer = setInterval(next, 5000);
    }
  }

  // Prev slide
  function prev() {
    current = current === 0 ? total - 1 : current - 1;
    update();
  }

  // Clear auto-slide timer
  function clearAutoSlide() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  // Auto-slide toggle
  if (autoSlideCheckbox) {
    autoSlideCheckbox.checked = false; // Default off
    autoSlideCheckbox.onchange = function() {
      var checked = this.checked;
      if (checked) {
        autoSlide = true;
        timer = setInterval(next, 5000);
      } else {
        autoSlide = false;
        clearAutoSlide();
      }
    };
  }

  // Toggle TOC sidebar
  function toggleTOC() {
    tocVisible = !tocVisible;
    toc.style.display = tocVisible ? 'block' : 'none';
    toc.classList.toggle('visible', tocVisible);

    if (tocVisible) {
      main.setAttribute('data-closed', 'false');
    } else {
      main.setAttribute('data-closed', 'true');
    }

    // Update button states
    if (tocNavBtn) {
      tocNavBtn.textContent = tocVisible ? '↩️' : '❌';
    }

    if (tocClosedBtn) {
      tocClosedBtn.style.display = tocVisible ? 'none' : 'inline-block';
    }
  }

  // Button events
  if (prevBtn) prevBtn.addEventListener('click', prev);
  if (nextBtn) nextBtn.addEventListener('click', next);

  if (tocNavBtn) tocNavBtn.addEventListener('click', toggleTOC);
  if (tocClosedBtn) tocClosedBtn.addEventListener('click', toggleTOC);

  // Toggle sidebar on content click
  main.addEventListener('click', function(e) {
    if (e.target === toc) {
      toggleTOC();
    }
  });

  // Sidebar click to close on mobile
  toc.addEventListener('click', function(e) {
    if (tocVisible && e.target === toc) {
      toggleTOC();
    }
  });

  // Keyboard navigation
  document.addEventListener('keydown', function(e) {
    // Don't prevent default if input focused
    if (e.target && e.target.tagName === 'INPUT') return;

    switch (e.key) {
      case 'ArrowRight':
      case 'ArrowDown':
      case 'Enter':
      case ' ':
        gotoSlide(current + 1);
        e.preventDefault();
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        gotoSlide(current - 1);
        e.preventDefault();
        break;
      case 'n':
      case 'N':
        // Toggle TOC with 'N' key
        toggleTOC();
        e.preventDefault();
        break;
      case 'Escape':
        if (document.fullscreenElement) {
          document.exitFullscreen();
        }
        e.preventDefault();
        break;
      case 'Home':
        current = 0;
        update();
        e.preventDefault();
        break;
      case 'End':
        current = total - 1;
        update();
        e.preventDefault();
        break;
      case 't':
      case 'T':
        toggleTOC();
        e.preventDefault();
        break;
    }
  });

  // Touch swipe
  var touchStartY = 0, touchEndY = 0;
  main.addEventListener('touchstart', function(e) {
    touchStartY = e.changedTouches[0].screenY;
  }, false);

  main.addEventListener('touchend', function(e) {
    touchEndY = e.changedTouches[0].screenY;
    if (touchEndY - touchStartY > 50) { // Swipe down
      gotoSlide(current + 1);
    }
    if (touchStartY - touchEndY > 50) { // Swipe up
      gotoSlide(current - 1);
    }
  }, false);

  // Auto-slide on mouse up
  document.addEventListener('mousedown', clearAutoSlide);
  document.addEventListener('mouseup', function() {
    if (autoSlide) {
      timer = setInterval(next, 5000);
    }
  });

  // Initial setup
  if (tocNavBtn) tocNavBtn.textContent = '❌';
  if (tocClosedBtn) tocClosedBtn.style.display = 'none';

  generateTOC();
  update();

  // Start auto-slide if enabled
  if (autoSlideCheckbox && autoSlideCheckbox.checked) {
    autoSlide = true;
    timer = setInterval(next, 5000);
  }

});

