  border: none;
  color: var(--text-color);
  display: none;
}

.slide.active,
.slide.slide-active {
  display: flex;
  flex-grow: 1;
  border-radius: 0;
}

.slide.hidden-content,
.slide:not(.active) {
  display: none;
}

