      counter = document.getElementById('counter'),
      toc = document.getElementById('toc'),
      slides = document.querySelectorAll('.outline-2');

  // Set current pager page index
  var currentPager = 0,
      totalPagers = pages.length,
      pagesVisible = [],
      visibleCount = Math.min(3, totalPagers),
      pagerTimer = null,
      autoPager = false;

  // Initialize pager
  function initPager() {
    if (!pages.length) return;

    // Generate pager pages
    pages.forEach(function(page, i) {
      var btn = document.createElement('button');
      btn.className = 'btn-pager';
      btn.setAttribute('data-index', i);
      btn.setAttribute('aria-label', page.getAttribute('aria-label') || 'Go to pager page ' + (i + 1));
      if (i === currentPager) {
        btn.classList.add('active');
      }
      btn.addEventListener('click', function() {
        gotoPagerPage(i);
      });
      pagerNav.appendChild(btn);
      pages[i].parentNode.removeChild(pages[i]); // Remove hidden pages
    });

    // Set visible pages
    updatePager();
  }

  // Update pager visibility
  function updatePager() {
    if (!pages.length) return;

    // Create pager buttons
    var pagerItems = pagerNav.querySelector('.pager-items') || pagerNav;
    if (!pagerItems) return;

    pagerItems.innerHTML = '';

    // Show appropriate number of active pages
    for (var i = 0; i < totalPagers; i++) {
      var li = document.createElement('li');
      var btn = document.createElement('button');
      btn.className = 'btn-pager';
      btn.setAttribute('data-pager', i);
      btn.textContent = i + 1;
      btn.setAttribute('aria-label', 'Go to pager page ' + (i + 1));

      // Mark active pager page
      if (i === currentPager) {
        btn.classList.add('active');
      }

      btn.addEventListener('click', function() {
        gotoPagerPage(parseInt(this.getAttribute('data-pager')));
      });

      pagerItems.appendChild(btn);
    }

    // Update counter
    if (counter) {
      counter.textContent = currentPager + 1 + ' / ' + totalPagers;
    }
  }

  // Go to pager page
  function gotoPagerPage(n) {
    if (n < 0) n = 0;
    if (n >= totalPagers) n = totalPagers - 1;
    currentPager = n;

    // Clear auto-pager
    if (autoPager) {
      clearAutoPager();
    }

    // Update pager visual
    updatePager();

    // If slides linked, update slides too
    if (slides.length > 0 && currentPager < slides.length) {
      gotoSlide(currentPager);
    }
  }

  // Next pager button
  function nextPager() {
    currentPager = currentPager >= totalPagers - 1 ? 0 : currentPager + 1;
    updatePager();

    if (autoPager) {
      pagerTimer = setInterval(nextPager, 5000); // Auto-pager interval
    }
  }

  // Prev pager button
  function prevPager() {
    currentPager = currentPager === 0 ? totalPagers - 1 : currentPager - 1;
    updatePager();
  }

  // Auto-pager toggle
  if (pager) {
    var autoPagerCheckbox = document.getElementById('auto-pager');
    if (autoPagerCheckbox) {
      autoPagerCheckbox.checked = false;
      autoPagerCheckbox.onchange = function() {
