document.addEventListener('DOMContentLoaded', function() {
  'use strict';

  // Get elements
  var toc = document.getElementById('toc-nav'),
      tocNavBtn = document.getElementById('toc-nav-toggle'),
      tocClosedBtn = document.getElementById('toc-nav-close'),
      mainContent = document.getElementById('main-content'),
      counter = document.getElementById('counter'),
      autoSlideCheckbox = document.getElementById('auto-slide'),
      slides = document.querySelectorAll('.outline-2');

  var current = 0,
      total = slides ? slides.length : 0,
      tocVisible = false,
      timer = null,
      tocList = toc ? toc.querySelector('ol') || toc.querySelector('ul') : null;

  // Generate TOC
  function generateTOC() {
    if (!toc || !tocList) return;

    tocList.innerHTML = '';
    slides.forEach(function(slide, i) {
      var li = document.createElement('li');
      var h1 = slide.querySelector('h1');
      if (h1) {
        li.textContent = (i + 1) + '. ' + h1.textContent;
      } else {
        var slideId = slide.id || 'slide' + i;
        var slideDesc = slide.textContent || slideId;
        li.textContent = (i + 1) + ' - ' + (slideDesc.length > 30 ? slideDesc.substring(0, 30) + '...' : slideDesc);
      }
      li.setAttribute('data-index', i);
      li.onclick = function() { gotoSlide(parseInt(this.getAttribute('data-index'))); };
      tocList.appendChild(li);
    });
  }

  // Update slide visibility
  function update() {
    if (!slides || slides.length === 0) return;

    slides.forEach(function(slide, i) {
      slide.style.display = 'none';
      slide.classList.remove('outline-active');
      slide.classList.remove('separation');

      if (i === current && !slide.classList.contains('hidden-content')) {
        slide.style.display = 'flex';
        slide.classList.add('outline-active');
        slide.classList.add('separation');
      }
    });

    // Update counter
    if (counter) {
      counter.textContent = (current + 1) + ' / ' + total;
    }

    // Update TOC active state
    var tocItems = tocList && tocList.querySelectorAll('li');
    if (tocItems) {
      tocItems.forEach(function(item) {
        if (parseInt(item.getAttribute('data-index')) === current) {
          item.style.background = '#eff6ff';
          item.classList.add('active');
        } else {
          item.style.background = '';
          item.classList.remove('active');
        }
      });
    }

    if (mainContent && toc) {
      mainContent.setAttribute('data-closed', tocVisible ? 'false' : 'true');
    }
  }

  // Go to slide
  function gotoSlide(n) {
    if (n < 0) n = total - 1;
    if (n >= total) n = 0;
    current = n;
    clearAutoSlide();
    update();
  }

  // Next slide
  function next() {
    current = current >= total - 1 ? 0 : current + 1;
    update();
    if (autoSlideCheckbox && autoSlideCheckbox.checked) {
      timer = setInterval(next, 5000);
    }
  }

  // Prev slide
  function prev() {
    current = current === 0 ? total - 1 : current - 1;
    update();
  }

  // Clear auto-slide
  function clearAutoSlide() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
    autoSlideCheckbox.checked = false;
    if (autoSlideCheckbox) {
      autoSlideCheckbox.onchange();
    }
  }

  // Auto-slide toggle
  if (autoSlideCheckbox) {
    autoSlideCheckbox.checked = false;
    autoSlideCheckbox.onchange = function() {
      var checked = this.checked;
      if (checked) {
        timer = setInterval(next, 5000);
      } else {
        clearAutoSlide();
      }
    };
  }

  // Toggle TOC
  function toggleTOC() {
    if (!toc) return;

    tocVisible = !tocVisible;
    toc.style.display = tocVisible ? 'flex' : 'none';
    toc.classList.toggle('visible', tocVisible);

    if (tocVisible) {
      mainContent.setAttribute('data-closed', 'false');
    } else {
      mainContent.setAttribute('data-closed', 'true');
    }

    if (tocNavBtn) {
      tocNavBtn.textContent = tocVisible ? '❌' : '✅';
      tocNavBtn.setAttribute('aria-label', tocVisible ? 'Close TOC' : 'Show TOC');
    }
    if (tocClosedBtn) {
      tocClosedBtn.style.display = tocVisible ? 'inline-block' : 'none';
    }

    if (mainContent.querySelector('.outline-active')) {
      mainContent.querySelector('.outline-active').focus();
    }
  }

  // Button events
  var prevBtn = document.querySelector('#prev');
  if (prevBtn) {
    prevBtn.addEventListener('click', prev);
  }

  var nextBtn = document.querySelector('#next');
  if (nextBtn) {
    nextBtn.addEventListener('click', next);
  }

  // TOC toggle button
  if (tocNavBtn) {
    tocNavBtn.addEventListener('click', toggleTOC);
  }

  // Sidebar click on mobile
  if (toc) {
    toc.addEventListener('click', function(e) {
      if (tocVisible && e.target === toc) {
        toggleTOC();
      }
    });
  }

  // Keyboard navigation
  document.addEventListener('keydown', function(e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

    switch (e.key) {
      case 'ArrowRight':
      case 'ArrowDown':
      case 'Enter':
      case ' ':
        gotoSlide(current + 1);
        e.preventDefault();
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        gotoSlide(current - 1);
        e.preventDefault();
        break;
      case 'n':
      case 'N':
        toggleTOC();
        e.preventDefault();
        break;
      case 'Escape':
        if (document.fullscreenElement) {
          document.exitFullscreen();
        } else if (toc) {
          toggleTOC();
        }
        e.preventDefault();
        break;
      case 'Home':
        current = 0;
        update();
        e.preventDefault();
        break;
      case 't':
      case 'T':
        toggleTOC();
        e.preventDefault();
        break;
      case 'b':
      case 'B':
        clearAutoSlide();
        e.preventDefault();
