/**
 * Professional SlideShow Styles
 * Elegant, readable, fully responsive
 */

:root {
  /* Light theme (default) */
  --bg-primary: #ffffff;
  --bg-secondary: #f8fafc;
  --bg-sidebar: #ffffff;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --brand: #6366f1;
  --brand-hover: #4f46e5;
  --accent: #06b6d4;
  --border: #e2e8f0;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
  --hover-bg: #f1f5f9;
}

[data-theme="dark"] {
  /* Dark theme */
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-sidebar: #1e293b;
  --text-primary: #f1f5f9;
  --text-secondary: #94a3b8;
  --brand: #818cf8;
  --brand-hover: #a5b4fc;
  --accent: #22d3ee;
  --border: #334155;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.3);
  --hover-bg: #334155;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  overflow-x: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Helvetica', 'Arial', sans-serif;
  font-size: 16px;
  line-height: 1.6;
}

/* App Container */
.app {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--bg-primary);
  color: var(--text-primary);
  transition: background-color 0.3s ease, color 0.3s ease;
}

/* Header */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border);
  transition: background-color 0.3s ease;
}

.logo {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--brand);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Main Content */
.main {
  flex: 1;
  display: flex;
  overflow: hidden;
  transition: all 0.3s ease;
}

/* Sidebar */
.sidebar {
  flex-shrink: 0;
  width: 5rem;
  background: var(--bg-sidebar);
  border-right: 1px solid var(--border);
  padding: 0.5rem;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--brand) var(--bg-sidebar);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  transition: all 0.3s ease;
}

.sidebar[hidden] {
  display: none;
}

.sidebar h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  padding: 0.25rem 0.5rem;
  text-align: center;
}

.toc {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.toc li {
  padding: 0.5rem 0.25rem;
  text-align: center;
  cursor: pointer;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 3px;
  transition: all 0.2s ease;
}

.toc li:hover {
  background: var(--hover-bg);
  color: var(--brand);
  transform: scale(1.02);
}

.toc li.active {
  background: var(--brand);
  color: white;
  font-weight: 600;
}

/* Slide Panel */
.slide-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 0;
}

.sliding {
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  scroll-behavior: smooth;
  padding: 1rem 2rem;
}

/* Individual Slide */
.slide {
  min-height: 70vh;
  padding: 0;
  margin: 0;
  border: none;
  background: transparent;
  transform: inherit;
  transition: all 0.3s ease;
  opacity: inherit;
  display: none;
}

.slide.active {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.slide h1 {
  color: var(--brand);
  font-size: 2rem;
  margin-bottom: 0.5rem;
  font-weight: 800;
  position: relative;
}

.slide h1::after {
  content: '';
  display: block;
  width: 60px;
  height: 4px;
  background: var(--brand);
  margin-top: 0.75rem;
  border-radius: 2px;
}

.slide p, .slide ul, .slide div {
  margin: 0.75rem 0;
  font-size: 1.05rem;
}

.slide ul {
  list-style: none;
  padding: 0;
}

.slide ul li {
  padding: 0.5rem 0;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.slide ul li::before {
  content: '→';
  color: var(--brand);
  font-weight: 600;
}

/* Slide Content */
.slide > p,
.slide > ul,
.slide > button,
.slide > div {
  width: 100%;
}

/* Navigation Buttons */
.nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  margin-top: auto;
}

.nav button {
  padding: 0.6rem 1rem;
  background: var(--brand);
  color: white;
  border: none;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
  box-shadow: var(--shadow);
}

.nav button:hover {
  background: var(--brand-hover);
  transform: translateY(-1px);
  box-shadow: 0 6px 8px -1px rgb(0 0 0 / 0.15);
}

.nav button:active {
  transform: translateY(0);
}

.nav button:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Counter */
.counter {
  font-size: 0.85rem;
  color: var(--text-secondary);
  padding: 0.25rem 0.75rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 10px;
}

/* Footer */
.footer {
  height: 3rem;
  padding: 0 1rem;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
  transition: background-color 0.3s ease;
}

/* Reload Hint */
.reload-hint {
  position: fixed;
  bottom: 4rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--brand);
  color: white;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: 4px;
  box-shadow: var(--shadow);
  white-space: nowrap;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateX(-50%) translateY(10px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

/* Scrollbar Styling */
.slide-panel::-webkit-scrollbar {
  width: 6px;
}

.slide-panel::-webkit-scrollbar-track {
  background: transparent;
}

.slide-panel::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 3px;
}

.slide-panel::-webkit-scrollbar-thumb:hover {
  background: var(--brand);
}

/* Theme Toggle */
#theme-toggle {
  padding: 0.5rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.8rem;
  color: var(--text-secondary);
  transition: all 0.2s ease;
}

#theme-toggle:hover {
  border-color: var(--brand);
  color: var(--brand);
}

/* Responsive Design */
@media(max-width: 768px) {
  .app {
    padding: 0.25rem;
  }

  .logo {
    font-size: 1rem;
  }

  .sidebar {
    padding: 0.25rem;
    width: 3rem;
  }

  .sidebar[hidden] .sidebar {
    width: auto;
  }

  .slide {
    padding: 1rem;
  }

  .slide h1 {
    font-size: 1.5rem;
  }

  .slide ul li {
    font-size: 0.9rem;
  }
}

@media(max-width: 480px) {
  .slide h1 {
    font-size: 1.25rem;
  }

  .reload-hint {
    bottom: 2rem;
    padding: 0.4rem 0.75rem;
    font-size: 0.75rem;
  }

  .slider-container {
    padding: 0.25rem;
  }

  .slide h1 {
    font-size: 1.25rem;
  }
}

/* Print Styles */
@media print {
  .nav, .counter, .reload-hint {
    display: none;
  }

  .slide-panel {
    overflow: visible;
  }

  .slide {
    page-break-after: always;
  }
}
