/**
 * Improved SlideShow JavaScript
 * - Navigation button connections
 * - Theme toggle (light/dark)
 * - Better UI interactions
 */

(function() {
  'use strict';

  // DOM Elements
  var slides = document.querySelectorAll('.slide'),
      toc = document.getElementById('toc'),
      counter = document.getElementById('counter'),
      nextBtn = document.getElementById('next'),
      prevBtn = document.getElementById('prev'),
      sidebar = document.getElementById('sidebar-toggle-btn'),
      themeBtn = document.getElementById('theme-btn'),
      toggleBtn = document.getElementById('theme-toggle'),
      main = document.querySelector('.main'),
      total = slides.length,
      current = 0;

  // Initialize TOC
  if (toc) {
    toc.innerHTML = "";
    slides.forEach(function(s, i) {
      var li = document.createElement('li');
      li.textContent = i + 1;
      li.dataset.slide = i;  // Store slide index for easier reference
      li.onclick = function() {
        gotoSlide(parseInt(this.dataset.slide));
      };
      toc.appendChild(li);
    });
  }

  /**
   * Go to specific slide
   * @param {number} index - 0-based slide index
   */
  function gotoSlide(index) {
    if (slides[current] && slides[current].classList) {
      slides[current].classList.remove('active');
    }
    slides[current].classList.remove('active');
    if (index >= 0 && index < total) {
      current = index;
      slides[current].classList.add('active');
      updateCounter();
    }
    toggleScroll();
    return current;
  }

  /**
   * Update slide counter
   */
  function updateCounter() {
    if (counter) {
      counter.textContent = (current + 1) + ' / ' + total;
    }
  }

  /**
   * Update main attribute to sync sidebar
   */
  function update() {
    if (sidebar && sidebar.classList) {
      sidebar.style.display = '';
      main.dataset.closed = sidebar.style.display === '' ? 'false' : 'true';
    }
  }

  /**
   * Toggle scroll state for sliding container
   */
  function toggleScroll() {
    if (slides[current]) {
      slides[current].scroll(0, 0);
    }
  }

  /**
   * Handle next button click
   */
  function onNext() {
    var next = current + 1;
    if (next < total) gotoSlide(next);
  }

  /**
   * Handle previous button click
   */
  function onPrev() {
    var prev = current - 1;
    if (prev >= 0) gotoSlide(prev);
  }

  /**
   * Toggle theme (light/dark)
   */
  function toggleTheme() {
    var isDark = document.body.dataset.theme === 'dark';
    var html = document.documentElement;

    if (!isDark) {
      // Switch to dark theme
      document.body.dataset.theme = 'dark';
      html.setAttribute('data-theme', 'dark');
      if (themeBtn) {
        themeBtn.textContent = '☀️ Dark';
      }
      if (toggleBtn) {
        toggleBtn.textContent = '☀️';
      }
    } else {
      // Switch to light theme
      document.body.dataset.theme = 'light';
      html.setAttribute('data-theme', 'light');
      if (themeBtn) {
        themeBtn.textContent = '🌙 Light';
      }
      if (toggleBtn) {
        toggleBtn.textContent = '🌙';
      }
    }
  }

  /**
   * Initialize event listeners
   */
  function init() {
    // Navigation buttons
    if (nextBtn) {
      nextBtn.addEventListener('click', onNext);
      nextBtn.addEventListener('keydown', function(e) {
        if (e.key === 'ArrowRight' || e.key === ' ') {
          e.preventDefault();
          onNext();
        }
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', onPrev);
      prevBtn.addEventListener('keydown', function(e) {
        if (e.key === 'ArrowLeft') {
          e.preventDefault();
          onPrev();
        }
      });
    }

    // Keyboard navigation
    document.addEventListener('keydown', function(e) {
      var key = e.key;
      if (key === 'ArrowRight' || key === ' ' && e.target.tagName !== 'BODY') {
        onNext();
      } else if (key === 'ArrowLeft') {
        onPrev();
      } else if (key === 'Home') {
        e.preventDefault();
        gotoSlide(0);
      } else if (key === 'End') {
        e.preventDefault();
        gotoSlide(total - 1);
      } else if (key === 'n') {
        e.preventDefault();
        onNext();
      } else if (key === 'p') {
        e.preventDefault();
        onPrev();
      }
    });

    // Sidebar toggle (click sidebar to close)
    if (sidebar && sidebar.dataset.slidePanel !== 'true') {
      sidebar.addEventListener('click', function() {
        main.dataset.closed = 'true';
        sidebar.dataset.slidePanel = 'true';
        slidePanel.style.display = 'flex';
        sidebar.style.display = 'none';
      }, { once: true });
    }

    // Theme toggle buttons
    if (themeBtn) {
      themeBtn.addEventListener('click', toggleTheme);
    }

    if (toggleBtn) {
      toggleBtn.addEventListener('click', toggleTheme);
    }

    // Initial state
    updateCounter();
    if (slides.length > 0) {
      slides[0].classList.add('active');
      updateCounter();
    }
  }

  // Wait for DOM to be ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
