// Initialize current slide index from DOM
function initCurrentIndex() {
    if (!container) return;
    // Check if any slide is already active
    const activeSlide = container.querySelector('.slide-active');
    if (activeSlide && activeSlide.id) {
        const match = activeSlide.id.match(/slide-(\d+)/);
        if (match) currentIndex = parseInt(match[1]);
    }
}

// Go to a slide
function goToSlide(index) {
    if (!container || !slides[0].classList.contains('slide-active')) {
        initCurrentIndex();
    }
    currentIndex = Math.max(0, Math.min(index, slides.length - 1));

    slides.forEach(slide => slide.classList.remove('slide-active'));
    slides[currentIndex].classList.add('slide-active');

