// Go to a slide
function goToSlide(index) {
    if (!container || !slides[0].classList.contains('slide-active')) {
        initCurrentIndex();
    }
    currentIndex = Math.max(0, Math.min(index, slides.length - 1));

    slides.forEach(slide => slide.classList.remove('slide-active'));
    slides[currentIndex].classList.add('slide-active');
    // slides[currentIndex].style.display = "block";

    const containerElement = container || document.getElementById('slides-panel');
    if (containerElement && slides[currentIndex]) {
        slides[currentIndex].scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}

function advance() {goToSlide(currentIndex + 1);}
function retreat() {goToSlide(currentIndex - 1);}
