/* Image and video */
img, video {
    max-width: 100%;
    height: auto;
    border-radius: 8px;
}

/**
 * Enhanced slide presentation
 * Version 2 - Proper slide management
 */

class SlideManager {
    constructor() {
        this.activeSlideIndex = 0;
        this.totalSlides = 0;
        this.slideElements = [];
        this.sidebar = null;
        this.toc = null;
        this.init();
    }

    init() {
        this.slideElements = document.querySelectorAll('.slide, .outline-2');
        this.totalSlides = this.slideElements.length;
        this.slideElements[0]?.classList.add('active');
        this.activeSlideIndex = 0;
        this.sidebar = document.querySelector('.sidebar');
        this.toc = document.getElementById('toc');
        this.updateSlides();
    }

    /**
     * Update visible slides based on state
     */
    updateSlides() {
        this.slideElements.forEach((el, i) => {
            el.classList.toggle('active', i === this.activeSlideIndex);
        });
        this.updateToc();
        this.updateCounter();
        this.updateNavButtons();
        this.updateControls();
    }

    /**
     * Update Table of Contents
     */
    updateToc() {
        if (!this.toc) return;

        const slides = Array.from(this.slideElements).filter(el => {
            // For outline-based slides, we need to check if it has h1
            const h1 = el.querySelector('h1');
            if (h1) {
                return h1.textContent && h1.textContent.trim() !== '';
            }
            // For non-outline slides, show if active
            return el.classList.contains('outline-2');
        });

        this.toc.innerHTML = slides.map((el, i) => {
            const h1 = el.querySelector('h1');
            const index = i;
            const isVisible = el.classList.contains('active');
            const title = h1 ? h1.textContent : 'Untitled';

            return `<li data-index="${index}">${title}</li>`;
        }).join('');

        // Update active state
        this.toc.querySelectorAll('li').forEach(li => {
            li.classList.toggle('active', parseInt(li.dataset.index) === this.activeSlideIndex);
        });
    }

    /**
     * Update slide counter
     */
    updateCounter() {
        const counter = document.getElementById('counter');
        if (counter) {
            counter.textContent = this.activeSlideIndex + 1 + ' / ' + this.totalSlides;
        }
    }

    /**
     * Update navigation buttons
     */
    updateNavButtons() {
        const prevBtn = document.getElementById('prev');
        const nextBtn = document.getElementById('next');

        if (prevBtn) {
            prevBtn.disabled = this.activeSlideIndex === 0;
        }
        if (nextBtn) {
            nextBtn.disabled = this.activeSlideIndex === this.totalSlides - 1;
        }
    }

    /**
     * Update visibility of controls
     */
    updateControls() {
        // Hide controls for non-slide pages
        const header = document.querySelector('.header');
        const outline = document.querySelector('.outline-2');

        if (header && outline) {
            // For pages with both header and outline, hide controls
            outline?.classList.add('hidden-controls');
        } else {
            outline?.classList.remove('hidden-controls');
        }
    }

    /**
     * Navigate to next slide
     */
    next() {
        if (this.activeSlideIndex < this.totalSlides - 1) {
            this.slideElements[this.activeSlideIndex]?.classList.remove('active');
            this.activeSlideIndex++;
            this.slideElements[this.activeSlideIndex]?.classList.add('active');
            this.hideSidebar();
            this.updateSlides();
            this.checkOutline();
            this.scrollToTop();
        }
    }

    /**
     * Navigate to previous slide
     */
    prev() {
        if (this.activeSlideIndex > 0) {
            this.slideElements[this.activeSlideIndex]?.classList.remove('active');
            this.activeSlideIndex--;
            this.slideElements[this.activeSlideIndex]?.classList.add('active');
            this.updateSlides();
            this.scrollIntoView();
        }
    }

    /**
     * Go to specific slide
     */
    goSlide(index) {
        if (index >= 0 && index < this.totalSlides) {
            this.slideElements[this.activeSlideIndex]?.classList.remove('active');
            this.activeSlideIndex = index;
            this.slideElements[index]?.classList.add('active');
            this.updateSlides();
            this.scrollIntoView();
        }
    }

    /**
     * Toggle sidebar
     */
    toggleSidebar() {
        if (this.sidebar) {
            this.sidebar.style.display = this.sidebar.style.display === 'none' ? 'flex' : 'none';
        }
    }

    /**
     * Hide sidebar
     */
    hideSidebar() {
        if (this.sidebar) {
            this.sidebar.style.display = 'none';
        }
    }

    /**
     * Show sidebar
     */
    showSidebar() {
        if (this.sidebar) {
            this.sidebar.style.display = 'flex';
        }
    }

    /**
     * Scroll into view
     */
    scrollIntoView() {
        const activeSlide = document.getElementById('slide-' + this.activeSlideIndex);
        if (activeSlide) {
            const panel = document.querySelector('#slide-panel, .slide-panel');
            if (panel) {
                panel.scrollTop = activeSlide.offsetTop - panel.offsetTop;
            }
        }
    }

    /**
     * Scroll to top
     */
    scrollToTop() {
        const panel = document.querySelector('#slide-panel, .slide-panel');
        if (panel) {
            panel.scrollTo({ top: 0, behavior: 'smooth' });
        }
    }

    /**
     * Check for outline elements
     */
    checkOutline() {
        const outline = document.querySelector('.outline-2');
        if (outline) {
            outline.classList.remove('outline-2');
            outline.classList.add('slide-active');
        }
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    const slides = new SlideManager();
    slides.hideSidebar();
    slides.updateControls();

    // Keyboard navigation
    document.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowRight' || e.key === ' ') {
            e.preventDefault();
            slides.next();
        } else if (e.key === 'ArrowLeft') {
            e.preventDefault();
            slides.prev();
        } else if (e.key === 'End') {
            slides.goSlide(slides.totalSlides - 1);
        } else if (e.key === 'Home') {
            slides.goSlide(0);
        }
    });

    // Button listeners
    const prevBtn = document.getElementById('prev');
    const nextBtn = document.getElementById('next');

    if (prevBtn) {
        prevBtn.addEventListener('click', () => slides.prev());
    }

    if (nextBtn) {
        nextBtn.addEventListener('click', () => slides.next());
    }

    // Global navigation
    window.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowRight' || e.key === ' ') {
            slides.next();
        } else if (e.key === 'ArrowLeft') {
            slides.prev();
        }
    });
});

// Export for external access
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { SlideManager };
}

