    transition: all 0.2s ease;
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    text-decoration: none;
}

nav-btn:hover {
    background: var(--primary);
    border-color: var(--primary);
    transform: translateY(-1px);
}

nav-btn:active {
    transform: translateY(0);
}

nav-btn:focus {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

nav-btn.disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

nav-btn.disabled:hover {
    background: var(--bg-secondary);
}

nav-btn svg {
    width: 1.25rem;
    height: 1.25rem;
}

nav-btn span {
    font-size: 0.875rem;
}

.counter {
    font-size: 0.75rem;
    color: var(--text-muted);
    margin: 0 0.5rem;
}

/* Main content with slides */
.main {
    flex: 1;
    padding: 1rem;
    overflow-y: auto;
    max-width: 1200px;
    margin: 0 auto;
}

/* Sidebar toggle */
.sidebar-toggle {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    color: var(--text);
    padding: 0.375rem 0.625rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    transition: all 0.2s ease;
}

.sidebar-toggle:hover {
    background: var(--primary);
    border-color: var(--primary);
}

.sidebar-toggle:focus {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

/* Sidebar */
.sidebar {
    flex: 0 0 180px;
    margin-right: 1rem;
    position: sticky;
    top: 60px; /* Below header */
    background: var(--bg-primary);
    border: 1px solid var(--border);
    border-radius: 0.5rem;
    padding: 0.75rem;
    max-height: calc(100vh - 60px);
    overflow-y: auto;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 0.75rem;
    padding: 0 0.25rem;
}

.sidebar-links {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.sidebar-link {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    padding: 0.5rem 0.75rem;
    border-radius: 0.375rem;
    color: var(--text);
    text-decoration: none;
    font-size: 0.875rem;
    transition: all 0.15s ease;
}

.sidebar-link:hover {
    background: var(--bg-secondary);
}

.sidebar-link.active {
    background: var(--primary);
}

.sidebar-link svg {
    width: 1.125rem;
    height: 1.125rem;
    opacity: 0.7;
}

/* Slide panel */
.slide-panel {
    flex: 1;
}

.sliding {
    transition: opacity 0.3s ease;
}

/* Content */
.content {
    min-height: 400px;
}

/* Outline/h2 formatting */
.outline-2 {
    margin: 1rem 0;
}

.outline-2 h2 {
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--text);
    padding: 0.5rem 0.75rem;
    border-bottom: 2px solid var(--primary);
    margin-top: 1rem;
}

.outline-2 h2 .tag {
    font-size: 0.6rem;
    padding: 0.125rem 0.5rem;
    border-radius: 0.25rem;
    text-transform: uppercase;
    font-weight: 700;
    letter-spacing: 1px;
}

.outline-2 h2 .tag SLIDE {
    background: var(--primary);
}

.outline-2 h2 .tag NOSLIDE,
.outline-2 h2 .tag NOSLIDES {
    background: var(--bg-secondary);
}

/* Outline text */
.outline-2 .outline-text-2 {
    padding: 0.75rem;
    background: transparent;
}

/* Lists */
.org-dl {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1rem;
}

.org-dl dt {
    font-weight: 600;
    color: var(--primary);
}

.org-dl dd {
    margin: 0;
    padding: 0.5rem;
    background: var(--bg-secondary);
    border-radius: 0.375rem;
}

/* Code blocks */
pre {
    background: var(--code-bg);
    padding: 1rem;
    border-radius: 0.5rem;
    overflow-x: auto;
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 0.85rem;
    border: 1px solid var(--border);
    line-height: 1.6;
}

pre code {
    font-family: inherit;
}

/* Tables */
table {
    border-collapse: collapse;
    width: 100%;
    margin: 1rem 0;
}

table th,
table td {
    padding: 0.75rem;
    border: 1px solid var(--border);
    text-align: left;
}

table th {
    background: var(--bg-secondary);
    font-weight: 600;
}

table caption {
    font-weight: 600;
    margin-bottom: 0.5rem;
    color: var(--text-muted);
}

/* Source container */
.org-src-container {
    border: 1px solid var(--border);
    border-radius: 0.5rem;
    background: var(--code-bg);
    margin: 1rem 0;
    overflow: hidden;
}

.org-src-container pre {
    margin: 0;
}

/* Button */
button {
    background: var(--primary);
    border: none;
    color: white;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
    transition: background 0.2s ease;
}

button:hover {
    background: var(--primary-dark);
}

button:focus {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

/* Responsive */
@media (max-width: 768px) {
    .sidebar {
        display: none;
    }

    .org-dl {
        grid-template-columns: 1fr;
    }

    .nav-buttons {
        flex-direction: column;
    }

    nav-btn {
        width: 100%;
        justify-content: center;
    }
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
    background: var(--bg-secondary);
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--border);
}

/* Animation */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

.slide-panel {
    animation: fadeIn 0.5s ease;
}

/* Footer area */
.footer {
    text-align: center;
    padding: 1rem;
    background: var(--bg-header);
    border-top: 1px solid var(--border);
    font-size: 0.75rem;
    color: var(--text-muted);
}

/* Fullscreen controls */
.fullscreen-controls {
    display: none;
}

@media (pointer: coarse) {
    /* For touch devices */
}

/* Print styles */
@media print {
    .header,
    .footer,
    .nav-buttons {
        display: none;
    }

    body {
        background: white;
        color: black;
    }
}

/**
 * SlideShow Navigation and Interactivity
 * Handles slide navigation, state management, and DOM updates
 */

(function() {
    'use strict';

    // Configuration
    const CONFIG = {
        totalSlides: 6,          // Total number of slides (can be determined dynamically)
        slideHeight: 600,        // Approximate height per slide in pixels
        defaultView: 'all',     // 'all' or 'one'
        autoScroll: false,      // Auto-scroll to current slide
        sidebarDefault: false,  // Default sidebar state (collapsed = false)
    };

    // State
    let state = {
        currentSlide: 1,
        viewMode: 'all',        // 'all' or 'one'
        slidesToc: [],          // Table of contents for sidebar
        containerHeight: 0,
        isMobile: false,
        sidebarOpen: false,
    };

    // DOM Elements
    const elements = {
        app: null,
        main: null,
        sidebar: null,
        slidesTocList: null,
        header: null,
        pager: null,
        logo: null,
        prevBtn: null,
        nextBtn: null,
        counter: null,
        sidebarToggle: null,
        slides: {},             // Map of slide index to element
        outlineElements: [],    // Array of h2 elements for each slide
    };

    // Initialize
    function init() {
        cacheDOM();
        setupKeyboardNavigation();
        determineSlides();
        setupViewButtons();
        setupSliderButtons();
        updateState();
        updateCounter();
        updateSlideContents();
        setupOutlineLinks();
        updateSidebar();
    }

    // Cache DOM elements
    function cacheDOM() {
        elements.app = document.querySelector('.app');
        elements.main = document.querySelector('.main');
        elements.sidebar = document.querySelector('.sidebar');
        elements.slidesTocList = document.querySelector('#toc-list');
        elements.header = document.querySelector('.header');
        elements.pager = document.querySelector('.pager');
        elements.logo = document.querySelector('.logo');
        elements.prevBtn = document.querySelector('#prev');
        elements.nextBtn = document.querySelector('#next');
        elements.counter = document.querySelector('.counter');
        elements.sidebarToggle = document.querySelector('.sidebar-toggle');
    }

    // Determine slides
    function determineSlides() {
        const contentSection = document.querySelector('.outline-2');
        if (!contentSection) return;

        const outlineSections = contentSection.querySelectorAll('.outline-2');

        outlineSections.forEach((section, index) => {
            const h2 = section.querySelector('h2');
            const title = h2 ? h2.textContent.trim() : 'Slide ' + (index + 1);
            const tag = section.querySelector('.tag .tag') || section.querySelector('.tag');
            const tagType = tag ? tag.textContent.trim() : '';

            elements.slides[index + 1] = {
                element: section,
                title: title,
                tagType: tagType,
            };
        });
    }

    // Setup keyboard navigation
    function setupKeyboardNavigation() {
        document.addEventListener('keydown', (e) => {
            if (e.target === document.body || e.target.tagName.toLowerCase() !== 'a') {
                if (e.key === 'ArrowLeft' || e.key === 'h') {
                    e.preventDefault();
                    navigateTo(Math.max(1, state.currentSlide - 1));
                } else if (e.key === 'ArrowRight' || e.key === 'l') {
                    e.preventDefault();
                    navigateTo(Math.min(CONFIG.totalSlides, state.currentSlide + 1));
                } else if (e.key === 'j') {
                    e.preventDefault();
                    navigateNext();
                } else if (e.key === 'k') {
                    e.preventDefault();
                    navigatePrev();
                }
            }
        });
    }

    // Setup view buttons
    function setupViewButtons() {
        const viewBtns = document.querySelectorAll('a[data-view]');
        viewBtns.forEach((btn, idx) => {
            btn.addEventListener('click', () => {
                const viewModes = ['all', 'one'];
                const newMode = viewModes[idx % viewModes.length];
                setViewMode(newMode);
            });
        });
    }

    // Setup slider buttons (prev/next)
    function setupSliderButtons() {
        elements.prevBtn?.addEventListener('click', () => navigatePrev());
        elements.nextBtn?.addEventListener('click', () => navigateNext());
        elements.sidebarToggle?.addEventListener('click', toggleSidebar);
    }

    // Navigate to specific slide
    function navigateTo(slideNum) {
        if (slideNum < 1 || slideNum > CONFIG.totalSlides) return;

        state.currentSlide = slideNum;

        const section = elements.slides[slideNum]?.element;
        if (section) {
            const rect = section.getBoundingClientRect();
            const windowHeight = window.innerHeight;
            const middleOfWindow = windowHeight / 2;

            if (CONFIG.autoScroll) {
                const slideFromTop = rect.top + rect.height / 2 - middleOfWindow;
                window.scrollTo({
                    top: window.scrollY + slideFromTop,
                    behavior: 'smooth'
                });
            }
        }

        updateSlideContents();
        updateCounter();
        updateSlideClasses();

        // Auto-collapse sidebar on mobile when sliding
        if (state.isMobile && CONFIG.viewMode === 'one') {
            toggleSidebar();
        }
    }

    // Navigate to next slide
    function navigateNext() {
        if (state.currentSlide < CONFIG.totalSlides) {
            navigateTo(state.currentSlide + 1);
        }
    }

    // Navigate to previous slide
    function navigatePrev() {
        if (state.currentSlide > 1) {
            navigateTo(state.currentSlide - 1);
        }
    }

    // Set view mode
    function setViewMode(mode) {
        state.viewMode = mode;

        // Update button states
        document.querySelectorAll('a[data-view]').forEach((btn, idx) => {
            const modeName = ['all', 'one'][idx];
            btn.classList.toggle('active', mode === modeName);
        });

        // Toggle sidebar on mode change
        if (CONFIG.sidebarDefault && mode === 'all') {
            state.sidebarOpen = true;
            elements.sidebarToggle?.classList.toggle('expanded', true);
        } else if (mode === 'one') {
            state.sidebarOpen = false;
            elements.sidebarToggle?.classList.toggle('expanded', false);
        }

        toggleSidebar();
    }

    // Toggle sidebar
    function toggleSidebar() {
        state.sidebarOpen = !state.sidebarOpen;
        const wasOpen = state.sidebarOpen;
        state.sidebarOpen = !wasOpen;
        const isMobile = matchMedia('(max-width: 768px)').matches;
        CONFIG.viewMode = wasOpen ? 'all' : (state.sidebarOpen ? 'all' : 'one');

        // Update sidebar toggle button
        elements.sidebarToggle?.classList.toggle('expanded', state.sidebarOpen);

        // Update header display
        elements.header?.classList.toggle('no-sidebar', !state.sidebarOpen && !isMobile);

        // Update body padding
        document.body.style.overflow = state.sidebarOpen ? 'auto' : 'hidden';
        document.body.style.paddingRight = state.sidebarOpen ? '' : '180px';

        // Update sidebar visibility
        elements.sidebar?.classList.toggle('collapsed', !state.sidebarOpen);

        // Update view button visibility
        elements.sliderButton?.classList.toggle('slider-btn', state.sidebarOpen);

        // Update pager display
        if (!state.sidebarOpen) {
            CONFIG.viewMode = 'one';
        }

        // Refresh pager
        if (elements.pager && state.viewMode === 'all') {
            updatePager();
        }
    }

    // Update slide contents (show/hide slides)
    function updateSlideContents() {
        for (const [num, slide] of Object.entries(elements.slides)) {
            const isCurrent = parseInt(num) === state.currentSlide;

            if (state.viewMode === 'one') {
                if (isCurrent) {
                    slide.element.style.display = 'block';
                } else {
                    slide.element.style.display = 'none';
                }
            } else {
                slide.element.style.display = 'block';

                // Add/remove opacity and highlight classes
                if (isCurrent) {
                    slide.element.classList.add('is-current');
                    slide.element.classList.add('current');
                    slide.element.classList.remove('previous');
                    slide.element.classList.remove('next');
                } else {
                    slide.element.classList.remove('is-current');
                    slide.element.classList.remove('current');

                    if (parseInt(num) < state.currentSlide) {
                        slide.element.classList.add('previous');
                    } else {
                        slide.element.classList.add('next');
                    }
                }
            }
        }

        // Scroll to current slide
        if (!state.sidebarOpen && CONFIG.autoScroll) {
            const section = elements.slides[state.currentSlide]?.element;
            if (section) {
                section.scrollIntoView({
                    behavior: 'smooth',
                    block: 'center'
                });
            }
        }
    }

    // Update slide classes
    function updateSlideClasses() {
        Object.values(elements.slides).forEach((slide, idx) => {
            const num = idx + 1;
            const isCurrent = num === state.currentSlide;

            if (num > 1) {
                slide.element.classList.add('is-current', isCurrent);
            }

            if (isCurrent) {
                slide.element.classList.add('current');
                slide.element.classList.remove('previous', 'next');
            } else if (num < state.currentSlide) {
                slide.element.classList.add('previous');
                slide.element.classList.remove('next');
            } else {
                slide.element.classList.add('next');
                slide.element.classList.remove('previous');
            }
        });
    }

    // Update counter
    function updateCounter() {
        elements.counter?.textContent = `${state.currentSlide} / ${CONFIG.totalSlides}`;
        elements.pager?.textContent = `${state.currentSlide} / ${CONFIG.totalSlides}`;
        updatePager();
    }

    // Update pager
    function updatePager() {
        if (!elements.pager) return;

        const progress = ((state.currentSlide - 1) / (CONFIG.totalSlides - 1)) * 100;
        elements.pager.innerHTML = `
            <span class="counter">${state.currentSlide}</span>
            <span class="of">${CONFIG.totalSlides}</span>
            ${CONFIG.viewMode === 'one' ? `<span class="progress">${Math.round(progress)}%</span>` : ''}
            <svg style="display:${CONFIG.viewMode === 'all' ? 'none' : 'block'}; width:2rem; height:2rem; margin: 0 auto;">
                <circle cx="1" cy="1" r="1" fill="none" stroke="var(--text)" stroke-opacity="0.3" stroke-width="1"/>
                <circle cx="2" cy="2" r="2" fill="none" stroke="${CONFIG.viewMode === 'one' ? 'var(--primary)' : 'var(--text-muted)'}" stroke-opacity="${CONFIG.viewMode === 'one' ? '0.7' : '0.3'}" stroke-width="1"/>
            </svg>
        `;
    }

    // Update sidebar
    function updateSidebar() {
        elements.slidesTocList.innerHTML = '';

        Object.keys(elements.slides).forEach((numStr) => {
            const num = parseInt(numStr);
            const slide = elements.slides[num];

            if (!slide) return;

            const link = document.createElement('a');
            link.className = 'sidebar-link' + (num === state.currentSlide ? ' active' : '');
            link.setAttribute('data-slide', num);
            link.setAttribute('href', `#slide-${num}`);

            link.innerHTML = `
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <circle cx="12" cy="12" r="10"/>
                    <circle cx="12" cy="12" r="3"/>
                </svg>
                <span>${slide.title}</span>
            `;

            link.addEventListener('click', (e) => {
                e.preventDefault();
                navigateTo(num);
            });

            elements.slidesTocList.appendChild(link);
        });

        state.slidesToc = Object.keys(elements.slides).map((n) => parseInt(n));
    }

    // Setup outline links within each slide
    function setupOutlineLinks() {
        const outlineElements = document.querySelectorAll('.outline-2 h2');

        outlineElements.forEach((h2) => {
            // Check if this h2 is a slide or just subsection
            const isSlide = h2.parentElement.classList.contains('outline-2');
            if (!isSlide) return;

            const tag = h2.querySelector('.tag');
            if (!tag?.textContent.trim() === 'SLIDE') return;

            // Don't create links for current slide
            const num = parseInt(h2.parentElement.dataset.slideNum) || state.currentSlide;
            if (num === state.currentSlide) return;

            const link = document.createElement('a');
            link.className = 'slide-link';
            link.href = `#slide-${num}`;
            link.innerHTML = `
                <svg viewBox="0 0 24 24" width="14" height="14">
                    <path fill="currentColor" d="M8.59 16.59 13.17 11 8.59 6.41 10 5l6 6-6 6-1.41-1.41z"/>
                </svg>
            `;

            link.addEventListener('click', (e) => {
                e.preventDefault();
                navigateTo(num);
            });

            h2.appendChild(link);
            elements.outlineElements.push(link);
        });
    }

    // Update state
    function updateState() {
        // Determine container height
        const headerHeight = elements.header?.offsetHeight || 60;
        elements.containerHeight = window.innerHeight - headerHeight;
    }

    // Main view buttons
    const elements = {
        // ... existing elements
        // ... more elements
    };

    // Expose to window
    window.SlideShow = {
        init,
        navigateTo,
        navigateNext,
        navigatePrev,
        setViewMode,
        toggleSidebar,
        getState: () => ({ ...state }),

        // Expose methods for testing/debugging
        debug: {
            state,
            elements,
        }
    };

    // Auto-initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

