/* Dark theme with proper IDs and navigation */
:root {
    --bg-primary: #1e293b;
    --bg-secondary: #334155;
    --bg-dark: #111827;
    --bg-header: rgba(30, 41, 59, 0.95);
    --primary: #6366f1;
    --primary-dark: #4f46e5;
    --accent: #8b5cf6;
    --text: #e5e7eb;
    --text-muted: #9ca3af;
    --border: #374151;
    --code-bg: #374151;
    --slide-bg: #0f172a;
}

* {
    box-sizing: border-box;
}

body {
    background-color: var(--bg-primary);
    color: var(--text);
    font-family: 'Inter', system-ui, -apple-system, sans-serif;
    margin: 0;
    padding: 0;
    min-height: 100vh;
    font-size: 16px;
    line-height: 1.6;
}

/* Slide container */
.app {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
    position: relative;
    overflow: hidden;
}

/* Header with navigation buttons */
.header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.5rem 1rem;
    background: var(--bg-header);
    border-bottom: 1px solid var(--border);
    position: sticky;
    top: 0;
    z-index: 100;
    backdrop-filter: blur(8px);
}

.logo {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--text);
    text-decoration: none;
}

.pager {
    font-size: 0.85rem;
    color: var(--text-muted);
}

/* Navigation buttons */
.nav {
    color:#aaa;
    display: flex;
}

.nav-buttons {
    display: flex;
    gap: 0.5rem;
    align-items: center;
}

nav-btn {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    color: var(--text);
    padding: 0.5rem 0.75rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
    transition: all 0.2s ease;
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    text-decoration: none;
}

nav-btn:hover {
    background: var(--primary);
    border-color: var(--primary);
    transform: translateY(-1px);
}

nav-btn:active {
    transform: translateY(0);
}

nav-btn:focus {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

nav-btn.disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

nav-btn.disabled:hover {
    background: var(--bg-secondary);
}

nav-btn svg {
    width: 1.25rem;
    height: 1.25rem;
}

nav-btn span {
    font-size: 0.875rem;
}

.counter {
    font-size: 0.75rem;
    color: var(--text-muted);
    margin: 0 0.5rem;
}

/* Main content with slides */
.main {
    flex: 1;
    padding: 1rem;
    overflow-y: auto;
    max-width: 1200px;
    margin: 0 auto;
}

/* Sidebar toggle */
.sidebar-toggle {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    color: var(--text);
    padding: 0.375rem 0.625rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    transition: all 0.2s ease;
}

.sidebar-toggle:hover {
    background: var(--primary);
    border-color: var(--primary);
}

.sidebar-toggle:focus {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

/* Sidebar */
.sidebar {
    flex: 0 0 180px;
    margin-right: 1rem;
    position: sticky;
    top: 60px; /* Below header */
    background: var(--bg-primary);
    border: 1px solid var(--border);
    border-radius: 0.5rem;
    padding: 0.75rem;
    max-height: calc(100vh - 60px);
    overflow-y: auto;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 0.75rem;
    padding: 0 0.25rem;
}

.sidebar-links {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.sidebar-link {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    padding: 0.5rem 0.75rem;
    border-radius: 0.375rem;
    color: var(--text);
    text-decoration: none;
    font-size: 0.875rem;
    transition: all 0.15s ease;
}

.sidebar-link:hover {
    background: var(--bg-secondary);
}

.sidebar-link.active {
    background: var(--primary);
}

.sidebar-link svg {
    width: 1.125rem;
    height: 1.125rem;
    opacity: 0.7;
}

/* Slide panel */
.slide-panel {
    flex: 1;
}

.sliding {
    transition: opacity 0.3s ease;
}

/* Content */
.content {
    min-height: 400px;
}

/* Outline/h2 formatting */
.outline-2 {
    margin: 1rem 0;
}

.outline-2 h2 {
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--text);
    padding: 0.5rem 0.75rem;
    border-bottom: 2px solid var(--primary);
    margin-top: 1rem;
}

.outline-2 h2 .tag {
    font-size: 0.6rem;
    padding: 0.125rem 0.5rem;
    border-radius: 0.25rem;
    text-transform: uppercase;
    font-weight: 700;
    letter-spacing: 1px;
}

.outline-2 h2 .tag SLIDE {
    background: var(--primary);
}

.outline-2 h2 .tag NOSLIDE,
.outline-2 h2 .tag NOSLIDES {
    background: var(--bg-secondary);
}

/* Outline text */
.outline-2 .outline-text-2 {
    padding: 0.75rem;
    background: transparent;
}

/* Lists */
.org-dl {
    /* display: grid; */
    display: contents;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1rem;
}

.org-dl dt {
    font-weight: 600;
    color: var(--primary);
}

.org-dl dd {
    margin: 0;
    padding: 0.5rem;
    background: var(--bg-secondary);
    border-radius: 0.375rem;
    width:90%;
}

/* Code blocks */
pre {
    background: var(--code-bg);
    padding: 1rem;
    border-radius: 0.5rem;
    overflow-x: auto;
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 0.85rem;
    border: 1px solid var(--border);
    line-height: 1.6;
}

pre code {
    font-family: inherit;
}

/* Tables */
table {
    border-collapse: collapse;
    width: 100%;
    margin: 1rem 0;
}

table th,
table td {
    padding: 0.75rem;
    border: 1px solid var(--border);
    text-align: left;
}

table th {
    background: var(--bg-secondary);
    font-weight: 600;
}

table caption {
    font-weight: 600;
    margin-bottom: 0.5rem;
    color: var(--text-muted);
}

/* Source container */
.org-src-container {
    border: 1px solid var(--border);
    border-radius: 0.5rem;
    background: var(--code-bg);
    margin: 1rem 0;
    overflow: hidden;
}

.org-src-container pre {
    margin: 0;
}

/* Button */
button {
    background: var(--primary);
    border: none;
    color: white;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
    transition: background 0.2s ease;
}

button:hover {
    background: var(--primary-dark);
}

button:focus {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

/* Responsive */
@media (max-width: 768px) {
    .sidebar {
        display: none;
    }

    .org-dl {
        grid-template-columns: 1fr;
    }

    .nav-buttons {
        flex-direction: column;
    }

    nav-btn {
        width: 100%;
        justify-content: center;
    }
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
    background: var(--bg-secondary);
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--border);
}

/* Animation */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

.slide-panel {
    animation: fadeIn 0.5s ease;
}

/* Footer area */
.footer {
    text-align: center;
    padding: 1rem;
    background: var(--bg-header);
    border-top: 1px solid var(--border);
    font-size: 0.75rem;
    color: var(--text-muted);
}

/* Fullscreen controls */
.fullscreen-controls {
    display: none;
}

@media (pointer: coarse) {
    /* For touch devices */
}

/* Print styles */
@media print {
    .header,
    .footer,
    .nav-buttons {
        display: none;
    }

    body {
        background: white;
        color: black;
    }
}
.collapsed {
    display: none;
}
.previous {
    display: none;
}
.next {
    display: none;
}
.is-current{
    display: block;
}

/**
 * SlideShow Navigation and Interactivity
 * Handles slide navigation, state management, and DOM updates
 */

